<script setup lang="ts">
// import { RouterLink, RouterView } from 'vue-router'
// import HelloWorld from './components/HelloWorld.vue'
import { ref, reactive, onMounted, computed } from "vue";
import html2canvas from "html2canvas";
import JSZip from "jszip";
const html2canvasOptions = {
  "scale": 4
};

const storeImgList =  ref([
{
  "url":"data:image/jpeg;base64,",
  "name":"玻璃贴-测试",
  "storeName":"测试新增门店测试价格"
}]);
const folderName = ref("压缩包")
const downloadBase64File = (
  base64Data: string | Blob,
  filename: string,
  isZip?: boolean
) => {
  const element = document.createElement("a");
  element.href = isZip
    ? URL.createObjectURL(base64Data as Blob)
    : (base64Data as string);
  element.download = filename;
  element.click();
};

const base64ToBlob = (base64: string, type: string = "image/jpeg") => {
  const byteCharacters = atob(base64);
  const byteNumbers = new Array(byteCharacters.length);

  for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
  }

  const byteArray = new Uint8Array(byteNumbers);
  return new Blob([byteArray], { "type": type });
};

const handleDownload = () => {
  const zip = new JSZip();
  console.log('zip----123--',zip)
  const img = zip.folder(folderName.value);
  const target = document.querySelectorAll(".self-flow-qrcode-inner");
  if (target.length) {
    for (let i = 0; i < target.length; i++) {
      const item = storeImgList.value[i];
      html2canvas(target[i] as HTMLElement, html2canvasOptions).then((canvas) => {
        (img as JSZip).file(
          `${item.storeName}-${item.name}.png`,
          base64ToBlob(canvas.toDataURL("image/png").split(",")[1]),
          { base64: true }
        );

        i === target.length - 1 &&
          zip
            .generateAsync({ type: "blob" })
            .then((content) => {
              console.error('then---222222222',content);
              downloadBase64File(content, folderName.value, true);
            })
            .catch((err) => {
              console.error('catch---3333333333',err);
              // Loader.hide();
            })
            .finally((error) => {
              console.error('finally---1111111111',error);
              
              // Loader.hide();
            });
      });
    }
  } else {
    console.error('222222222');
    // Loader.hide();
  }
};
</script>

<template>
  <header>
    <h1>子应用</h1>
    <!-- <img alt="Vue logo" class="logo" src="@/assets/logo.svg" width="125" height="125" /> -->
    <!-- <router-view /> -->
    <!-- <div class="wrapper">
      <nav>
        <RouterLink to="/">Home</RouterLink>
        <RouterLink to="/about">About</RouterLink>
      </nav>
    </div> -->
    <div class="self-flow-qrcode-list">
      <img v-for="ele in storeImgList" class="self-flow-qrcode-inner" :key="ele.positionId" :src="ele.url" alt="">
    </div>
    <button @click="handleDownload">下载</button>

  </header>

  <!-- <RouterView /> -->
</template>

